                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            comps.append({
                "color": color, "cells": cells,
                "box": (min(ys), min(xs), max(ys), max(xs))
            })

    def contains(a, b):
        return (a[0] <= b[0] and a[1] <= b[1]
                and a[2] >= b[2] and a[3] >= b[3])

    # Group nested ring components under their outermost enclosing component.
    roots = []
    for i, comp in enumerate(comps):
        parents = [j for j, other in enumerate(comps)
                   if i != j and contains(other["box"], comp["box"])
                   and other["box"] != comp["box"]]
        if not parents:
            roots.append(i)

    out = [row[:] for row in grid]
    for root in roots:
        members = [i for i, comp in enumerate(comps)
                   if contains(comps[root]["box"], comp["box"])]
        members.sort(key=lambda i: (
