    # connected L-shaped groups according to their orientation.
    used = set()
    for r in range(h - 1):
        for c in range(w - 1):
            block = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if all(grid[x][y] == 8 for x, y in block) and not (block & used):
                for x, y in block:
                    out[x][y] = 1
                used |= block

    # Color residual groups by matching each group to a 2x2 L template.
    colors = {
        frozenset({(0, 1), (1, 0), (1, 1)}): 2,
        frozenset({(0, 0), (1, 0), (1, 1)}): 4,
        frozenset({(0, 0), (0, 1), (1, 0)}): 3,
        frozenset({(0, 0), (0, 1), (1, 1)}): 4,
    }
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 8 or (r, c) in used or (r, c) in seen:
                continue
            stack = [(r, c)]
            component = []
            seen.add((r, c))
            while stack:
                x, y = stack.pop()
                component.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 8 and (nx, ny) not in used and (nx, ny) not in seen:
